-- VALUES('b1835e4c-454e-4174-aebf-c7460546727d', '{"status": "Inserted", "data": [{"key": "primaryplandate", "data_type": "text", "new_value": "10/04/2023", "old_value": null, "display_name": "Permanency Plan Established Date"}, {"key": "concurrentplandate", "data_type": "text", "new_value": "2023-10-04T04:00:00.000Z", "old_value": null, "display_name": "Concurrent Plan Established Date"}, {"key": "primarypermanencytype", "data_type": "text", "new_value": "Reunification", "old_value": null, "display_name": "Primary Permanency Plan"}, {"key": "concurrentpermanencytype", "data_type": "text", "new_value": "GUARDR", "old_value": null, "display_name": "Concurrent Permanency Plan"}, {"key": "primaryarrangetype", "data_type": "text", "new_value": null, "old_value": null, "display_name": "primary arrange type"}, {"key": "remarks", "data_type": "text", "new_value": null, "old_value": null, "display_name": "Primary Permanency Plan Comments"}, {"key": "concurrentcomments", "data_type": "text", "new_value": null, "old_value": null, "display_name": "Concurrent Permanency Plan Comments"}, {"key": "courtorderreceived", "data_type": "text", "new_value": true, "old_value": null, "display_name": " Court order received and uploaded in CJAMS"}, {"key": "permanencyplanremainssame", "data_type": "text", "new_value": null, "old_value": null, "display_name": "Permanency Plan Remains the same"}, {"key": "permanencyplanremainssamedate", "data_type": "text", "new_value": null, "old_value": null, "display_name": "Review Date"}, 
-- {"key": "isInClosedProximity", "data_type": "text", "new_value": "0", "old_value": null, "display_name": "If the permanency plan is to return home or relative placement, is the placement in close proximity to the child's family?"}, {"key": "isInClosedProximityExpln", "data_type": "text", "new_value": "Rose currently resides at Second Family Inc, the closest group home in Maryland for medically fragile children. It is in Bowie, MD, approximately 2 hours and 15 minutes from her mother''s home in Salisbury.", "old_value": null, "display_name": "If the permanency plan is to return home or relative placement, is the placement in close proximity to the child's family? - Explanation required"}, {"key": "meetingSafetyNeedsExpln", "data_type": "text", "new_value": "Second Family, Inc provides 24/7 nursing care for Rose, including feedings, medication management, bathing, dressing, transportation to medical appointments, observation of her medical equipment, and engagement in social enrichment.  Rose appears to have adjusted well to the placement and will smile, laugh, and coo in response to staff engaging with her.", "old_value": null, "display_name": "Discuss how the caregiver is meeting the safety needs of the child as well as the appropriateness and the restrictiveness of the present placement, the child's adjustment to the placement, and how the placement meets the best interest and the special needs of the child. - Explanation required"}, {"key": "sixMonthsPlacementExpln", "data_type": "text", "new_value": "Rose was found CINA on May 3rd and was placed at Second Family, Inc. She has resided there since with no hospitalizations or respite placements. There are no anticipated changes in placement over the next six months.", "old_value": null, "display_name": "Discuss and explain changes in the child's placement during the last 6 months. Discuss any anticipated changes in placement in the next 6 months. - Explanation required  "}, {"key": "courtOrdersExpln", "data_type": "text", "new_value": "The LDSS worker transports Ms. Saint Fleur to Bowie on a weekly basis to visit Rose, or coordinates a ride for her if she is unable to do so herself. The LDSS worker is working to coordinate a Fit-to-parent evaluation for Ms. Saint Fleur. The local worker communicates with Ms. Saint Fleur regarding Rose''s medical, physical, and developmental needs. The Local Department worker meets with Ms. Saint Fleur to discuss service planning, and enters into service agreements with her. ", "old_value": null, "display_name": "Describe how the worker is carrying out specific court orders pertaining to the child. - Explanation required"}, {"key": "permToPermExpln", "data_type": "text", "new_value": "Not applicable.", "old_value": null, "display_name": "Document what steps have been taken to finalize the placement for children whose permanency plan is adoption or placement at another permanent home? - Explanation required"}, {"key": "parentname", "data_type": "text", "new_value": "2dfc84f2-c992-4c2b-898d-0d0a9321b511", "old_value": null, "display_name": "Parent 1 Name"}, {"key": "parent2name", "data_type": "text", "new_value": null, "old_value": null, "display_name": "Parent 2 Name"}, {"key": "safeAndCareExpln", "data_type": "text", "new_value": "The LDSS worker visits Rose on at least a monthly basis. The worker also completes additional visits when transporting Ms. Saint Fleur to see Rose. The LDSS worker coordinates care with Second Family staff, ensuring that Rose gets to her specialist appointments. The LDSS worker also ensures that SSI payments and insurance issues are resolved in a timely manner. The LDSS worker has met with Rose''s pediatrician to evaluate Rose''s need for 1:1 care and to address concerns about Rose''s neurological development. ", "old_value": null, "display_name": "Describe how the worker is ensuring that the child receives safe and appropriate care. Discuss specific outcomes of ongoing/past services that have been offered to the child during the assessment period? - Explanation required"}, {"key": "assessmentPeriodExpln", "data_type": "text", "new_value": "The LDSS worker offers weekly transportation to Ms. Saint Fleur to visit Rose. The LDSS worker also transported Ms. Saint Fleur to Rose''s cardiology appointment on July 17th. The LDSS worker met with Ms. Saint Fleur in her home on September 6th to discuss service planning. The LDSS worker has networked with various providers to inquire about Fit to Parent evaluation services.  ", "old_value": null, "display_name": "What efforts were made to promote permanency for the child during this assessment period? - Explanation required"}, {"key": "lifebookExpln", "data_type": "text", "new_value": "Not yet, pictures continue to be collected. ", "old_value": null, "display_name": "Has a Lifebook been prepared? If no, Explain?"},
--  {"key": "serviceAgreementExpln", "data_type": "text", "new_value": "Ms. Saint Fleur consistently accepts phone calls from the Department and is an active participant in conversations. She communicates with the Department regarding her goals and desires for reunification. She reports being highly motivated to reunify with her daughter. She, and the LDSS worker have created a service plan that includes goals such as visiting at least once per week, obtaining a cognitive evaluation, training with Second Family staff to care for Rose, going to Rose''s appointments, obtaining a more spacious living arrangement, and obtaining reliable transportation.", "old_value": null, "display_name": "Describe the parent’s compliance in developing and carrying out the terms of the Service Agreement. (Discuss specific outcomes during this assessment period). Describe the parent’s involvement including dates of case planning meetings, in working with the caseworker to develop the case plan. Discuss specific outcomes of ongoing and past services offered to the parent(s) during this assessment period, including times of participation and the results of any meetings. - Explanation required"}, {"key": "isProviderAgree", "data_type": "text", "new_value": "1", "old_value": null, "display_name": "Does the Provider agree with the Permanency Plan?"}, {"key": "isProviderAgreeExpln", "data_type": "text", "new_value": "Second Family continues to welcome Ms. Saint Fleur and her daughter Midjina into the house to visit Rose, and encourage her to ask questions about her care if she has any.", "old_value": null, "display_name": "Provider agree with the Permanency Plan? - Explanation required"}, {"key": "serviceAgreementForOtherExpln", "data_type": "text", "new_value": "Rose''s father, Mr. Madeus, has expressed interest in visiting Rose but not in taking care of her. Rose has one sister, Midjina, that resides with their mother Ms. Saint Fleur. Ms. Saint Fleur reports that she has another daughter age 12 who resides in Haiti. Ms. Saint Fleur identified a supportive cousin, Ms. Monette Jeune, who may be willing to train and help Rose. The LDSS worker will reach out to Ms. Jeune once she has her contact information.", "old_value": null, "display_name": "Discuss services being provided to other significant persons including contacts with siblings, extended family, permanent foster parents, prospective adoptive parents, etc.Describe the child's relationship with these significant others and/or any other relevant issues.Explain why child not placed with siblings, including how such placement would be contrary to the safety or well being of any of the siblings. - Explanation required"}, {"key": "reason", "data_type": "text", "new_value": null, "old_value": null, "display_name": "End Reason"}, {"key": "enddate", "data_type": "text", "new_value": null, "old_value": null, "display_name": "End Date"}, {"key": "achieveddate", "data_type": "text", "new_value": null, "old_value": null, "display_name": "Achieved Date"}]}', 'HISTORY', '16f83deb-935c-4aab-8e1d-9153d4f0553f', '86d4fa0a-b7b8-40ce-a8d8-7adae79cf0c7', NULL, '2023-10-04 00:00:00.000', NULL, '2023-10-04 04:00:00.000', 'MaryKatherineMeyers', NULL, NULL, '2023-10-19 11:41:46.000', '2023-10-19 11:41:46.000', 'b0d9acd0-847a-46b9-839e-8892fcd56148', '2023-10-19 11:41:46.000', 'b0d9acd0-847a-46b9-839e-8892fcd56148', 1, NULL, 'Reunification', 'GUARDR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'cce0d9e1-7233-4609-be1c-40e725414d52', NULL, '8426f362-186e-4c88-ac3f-857b858f44db', '{"lifebookExpln": "Not yet, pictures continue to be collected. ", "isProviderAgree": "1", "permToPermExpln": "Not applicable.", "courtOrdersExpln": "The LDSS worker transports Ms. Saint Fleur to Bowie on a weekly basis to visit Rose, or coordinates a ride for her if she is unable to do so herself. The 