-- VALUES('98e3548c-5b17-4257-8898-cf5305aa238b', '{"status": "Updated", "data": [{"key": "primaryplandate", "data_type": "text", "new_value": "2023-10-04T04:00:00.000Z", "old_value": "10/04/2023", "display_name": "Permanency Plan Established Date"}]}', 'HISTORY', '16f83deb-935c-4aab-8e1d-9153d4f0553f', '86d4fa0a-b7b8-40ce-a8d8-7adae79cf0c7', NULL, '2023-10-04 04:00:00.000', NULL, '2023-10-04 04:00:00.000', 'MaryKatherineMeyers', NULL, NULL, '2023-10-19 11:41:46.000', '2023-10-19 11:41:46.000', 'b0d9acd0-847a-46b9-839e-8892fcd56148', '2023-10-19 11:41:57.000', 'b0d9acd0-847a-46b9-839e-8892fcd56148', 1, NULL, 'Reunification', 'GUARDR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'cce0d9e1-7233-4609-be1c-40e725414d52', NULL, '8426f362-186e-4c88-ac3f-857b858f44db', '{"lifebookExpln": "Not yet, pictures continue to be collected. ", "isProviderAgree": "1", "permToPermExpln": "Not applicable.", "courtOrdersExpln": "The LDSS worker transports Ms. Saint Fleur to Bowie on a weekly basis to visit Rose, or coordinates a ride for her if she is unable to do so herself. The LDSS worker is working to coordinate a Fit-to-parent evaluation for Ms. Saint Fleur. The local worker communicates with Ms. Saint Fleur regarding Rose''s medical, physical, and developmental needs. The Local Department worker meets with Ms. Saint Fleur to discuss service planning, and enters into service agreements with her. ", "safeAndCareExpln": "The LDSS worker visits Rose on at least a monthly basis. The worker also completes additional visits when transporting Ms. Saint Fleur to see Rose. The LDSS worker coordinates care with Second Family staff, ensuring that Rose gets to her specialist appointments. The LDSS worker also ensures that SSI payments and insurance issues are resolved in a timely manner. The LDSS worker has met with Rose''s pediatrician to evaluate Rose''s need for 1:1 care and to address concerns about Rose''s neurological development. ", "isInClosedProximity": "0", "isProviderAgreeExpln": "Second Family continues to welcome Ms. Saint Fleur and her daughter Midjina into the house to visit Rose, and encourage her to ask questions about her care if she has any.", "assessmentPeriodExpln": "The LDSS worker offers weekly transportation to Ms. Saint Fleur to visit Rose. The LDSS worker also transported Ms. Saint Fleur to Rose''s cardiology appointment on July 17th. The LDSS worker met with Ms. Saint Fleur in her home on September 6th to discuss service planning. The LDSS worker has networked with various providers to inquire about Fit to Parent evaluation services.  ", "serviceAgreementExpln": "Ms. Saint Fleur consistently accepts phone calls from the Department and is an active participant in conversations. She communicates with the Department regarding her goals and desires for reunification. She reports being highly motivated to reunify with her daughter. She, and the LDSS worker have created a service plan that includes goals such as visiting at least once per week, obtaining a cognitive evaluation, training with Second Family staff to care for Rose, going to Rose''s appointments, obtaining a more spacious living arrangement, and obtaining reliable transportation.", "meetingSafetyNeedsExpln": "Second Family, Inc provides 24/7 nursing care for Rose, including feedings, medication management, bathing, dressing, transportation to medical appointments, observation of her medical equipment, and engagement in social enrichment.  Rose appears to have adjusted well to the placement and will smile, laugh, and coo in response to staff engaging with her.", "sixMonthsPlacementExpln": "Rose was found CINA on May 3rd and was placed at Second Family, Inc. She has resided there since with no hospitalizations or respite placements. There are no anticipated changes in placement over the next six months.", "isInClosedProximityExpln": "Rose currently resides at Second Family Inc, the closest group home in Maryland for medically fragile children. It is in Bowie, MD, approximately 2 hours and 15 minutes from her mother''s home in Salisbury.", "serviceAgreementForOtherExpln": "Rose''s father, Mr. Madeus, has expressed interest in visiting Rose but not in taking care of her. Rose has one sister, Midjina, that resides with their mother Ms. Saint Fleur. Ms. Saint Fleur reports that she has another daughter age 12 who resides in Haiti. Ms. Saint Fleur identified a supportive cousin, Ms. Monette Jeune, who may be willing to train and help Rose. The LDSS worker will reach out to Ms. Jeune once she has her contact information."}', NULL, NULL, '2dfc84f2-c992-4c2b-898d-0d0a9321b511', NULL, NULL, true, NULL, '{"permanencyplanid":"16f83deb-935c-4aab-8e1d-9153d4f0553f","primaryplandate":"2023-10-04T04:00:00.000Z","concurrentplandate":"2023-10-04T04:00:00.000Z","caseworkername":"MaryKatherineMeyers","primarypermanencytype":"Reunification","concurrentpermanencytype":"GUARDR","primaryarrangetype":null,"concurrentarrangetype":null,"remarks":null,"concurrentcomments":null,"courtorderreceived":true,"permanencyplanremainssame":null,"permanencyplanremainssamedate":null,"isreviewsubmit":1,"isInClosedProximity":"0","isInClosedProximityExpln":"Rose currently resides at Second Family Inc, the closest group home in Maryland for medically fragile children. It is in Bowie, MD, approximately 2 hours and 15 minutes from her mother''s home in Salisbury.","meetingSafetyNeedsExpln":"Second Family, Inc provides 24/7 nursing care for Rose, including feedings, medication management, bathing, dressing, transportation to medical appointments, observation of her medical equipment, and engagement in social enrichment.  Rose appears to have adjusted well to the placement and will smile, laugh, and coo in response to staff engaging with her.","sixMonthsPlacementExpln":"Rose was found CINA on May 3rd and was placed at Second Family, Inc. She has resided there since with no hospitalizations or respite placements. There are no anticipated changes in placement over the next six months.","courtOrdersExpln":"The LDSS worker transports Ms. Saint Fleur to Bowie on a weekly basis to visit Rose, or coordinates a ride for her if she is unable to do so herself. The LDSS worker is working to coordinate a Fit-to-parent evaluation for Ms. Saint Fleur. The local worker communicates with Ms. Saint Fleur regarding Rose''s medical, physical, and developmental needs. The Local Department worker meets with Ms. Saint Fleur to discuss service planning, and enters into service agreements with her. ","permToPermExpln":"Not applicable.","parentname":"2dfc84f2-c992-4c2b-898d-0d0a9321b511","parent2name":null,"safeAndCareExpln":"The LDSS worker visits Rose on at least a monthly basis. The worker also completes additional visits when transporting Ms. Saint Fleur to see Rose. The LDSS worker coordinates care with Second Family staff, ensuring that Rose gets to her specialist appointments. The LDSS worker also ensures that SSI payments and insurance issues are resolved in a timely manner. The LDSS worker has met with Rose''s pediatrician to evaluate Rose''s need for 1:1 care and to address concerns about Rose''s neurological development. ","assessmentPeriodExpln":"The LDSS worker offers weekly transportation to Ms. Saint Fleur to visit Rose. The LDSS worker also transported Ms. Saint Fleur to Rose''s cardiology appointment on July 17th. The LDSS worker met with Ms. Saint Fleur in her home on September 6th to discuss service planning. The LDSS worker has networked with various providers to inquire about Fit to Parent evaluation services.  ","lifebookExpln":"Not yet, pictures continue to be collected. ","serviceAgreementExpln":"Ms. Saint Fleur consistently accepts phone calls from the Department and is an active participant in conversations. She communicates with the Department regarding her goals and desires for reunification